// Read-only browser acceptance of reports already generated by the real model.
// Every non-GET API request is blocked so this check cannot enqueue analysis.
const fs = require('node:fs');
const path = require('node:path');
const { chromium } = require(path.join(process.env.USERPROFILE, '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'));

const base = (process.argv[2] || 'http://127.0.0.1:8766').replace(/\/$/, '');
const output = path.resolve(process.argv[3] || 'data/live-framework-evaluation/browser');
fs.mkdirSync(output, { recursive: true });

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = [];
  page.on('pageerror', (error) => errors.push(error.message));
  await page.route('**/api/**', (route) => route.request().method() === 'GET' ? route.continue() : route.abort());
  try {
    for (const id of [171, 174, 173, 188]) {
      await page.goto(`${base}/projects/${id}`, { waitUntil: 'networkidle' });
      const report = page.locator('.agent-report').first();
      await report.waitFor();
      const text = await report.innerText();
      if (!text.includes('机会判断') || text.length < 100) throw new Error(`Missing report for ${id}`);
      if (id === 174 && !text.includes('钢材')) throw new Error('Steel scope missing');
      if (id === 188 && !text.includes('定向钻机')) throw new Error('Drill exclusion missing');
      await report.scrollIntoViewIfNeeded();
      await page.screenshot({ path: path.join(output, `project-${id}-desktop.png`) });
      if (id === 174) {
        await report.getByRole('button', { name: '保存快照' }).first().click();
        const drawer = page.locator('.ant-drawer-body');
        await drawer.locator('.detail-attachment-snapshot-text').waitFor();
        if (!(await drawer.innerText()).includes('普碳中板')) throw new Error('Saved attachment snapshot missing');
        await page.waitForTimeout(350);
        await page.screenshot({ path: path.join(output, 'attachment-snapshot.png') });
        await page.locator('.ant-drawer-close').click();
      }
      await page.setViewportSize({ width: 390, height: 844 });
      await page.waitForTimeout(150);
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      if (overflow > 1) throw new Error(`Mobile page overflow for ${id}: ${overflow}`);
      await page.screenshot({ path: path.join(output, `project-${id}-mobile.png`) });
      await page.setViewportSize({ width: 1440, height: 1000 });
      console.log(JSON.stringify({ project: id, report: true, mobile: true }));
    }
    if (errors.length) throw new Error(errors.join('\n'));
  } finally {
    await browser.close();
  }
})().catch((error) => { console.error(error.stack || error); process.exitCode = 1; });
